// n8n Code Node - Extract Personalization Data from HTML

const html = $input.first().json.data; // Adjust based on your input field name

// Helper function to clean text
function cleanText(text) {
  return text
    .replace(/\s+/g, ' ')
    .replace(/\n\s*\n/g, '\n')
    .trim();
}

// Helper function to extract text between tags
function extractBetween(html, startPattern, endPattern) {
  const regex = new RegExp(startPattern + '([\\s\\S]*?)' + endPattern, 'gi');
  const matches = [];
  let match;
  while ((match = regex.exec(html)) !== null) {
    matches.push(cleanText(match[1].replace(/<[^>]*>/g, ' ')));
  }
  return matches;
}

// Remove scripts, styles, and comments
let content = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, '');

// Extract company name from title
const titleMatch = content.match(/<title[^>]*>([^<]+)<\/title>/i);
const pageTitle = titleMatch ? cleanText(titleMatch[1]) : '';

// Extract meta description
const metaDescMatch = content.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const metaDescription = metaDescMatch ? cleanText(metaDescMatch[1]) : '';

// Extract company name from schema
const schemaMatch = content.match(/"name":\s*"([^"]+)"/);
const companyName = schemaMatch ? schemaMatch[1] : '';

// Extract phone numbers
const phoneMatches = content.match(/(?:tel:|href="tel:)([^"<\s]+)/gi) || [];
const phones = [...new Set(phoneMatches.map(p => p.replace(/tel:|href="tel:/gi, '')))];

// Extract address from schema or content
const addressMatch = content.match(/"streetAddress":\s*"([^"]+)"[\s\S]*?"addressLocality":\s*"([^"]+)"[\s\S]*?"addressRegion":\s*"([^"]+)"[\s\S]*?"postalCode":\s*"([^"]+)"/);
const address = addressMatch 
  ? `${addressMatch[1]}, ${addressMatch[2]}, ${addressMatch[3]} ${addressMatch[4]}`
  : '';

// Extract services from navigation/menu
const servicesMatch = content.match(/dropdown-menu">([\s\S]*?)<\/ul>/gi) || [];
const services = [];
servicesMatch.forEach(menu => {
  const items = menu.match(/dropdown-item[^>]*>([^<]+)</gi) || [];
  items.forEach(item => {
    const service = item.replace(/dropdown-item[^>]*>|</gi, '').trim();
    if (service && !services.includes(service)) {
      services.push(service);
    }
  });
});

// Extract company values
const values = [];
const valueMatches = content.match(/<span>([^<]+):<\/span>\s*([^<]+)/gi) || [];
valueMatches.forEach(v => {
  const parts = v.match(/<span>([^<]+):<\/span>\s*([^<]+)/i);
  if (parts) {
    values.push({ name: parts[1].trim(), description: parts[2].trim() });
  }
});

// Extract team members
const teamMembers = [];
const teamSection = content.match(/GET TO KNOW THE TEAM[\s\S]*?<\/div>\s*<\/div>\s*<\/div>/i);
if (teamSection) {
  const memberMatches = teamSection[0].match(/<h5>([^<]+)<\/h5>\s*<h6>([^<]+)<\/h6>/gi) || [];
  memberMatches.forEach(m => {
    const parts = m.match(/<h5>([^<]+)<\/h5>\s*<h6>([^<]+)<\/h6>/i);
    if (parts) {
      teamMembers.push({ name: parts[1].trim(), role: parts[2].trim() });
    }
  });
}

// Extract service areas/cities
const cities = [];
const cityMatches = content.match(/<h5>([A-Za-z\s]+)<\/h5>\s*(?:<a[^>]*>)?AC Repair/gi) || [];
cityMatches.forEach(c => {
  const city = c.match(/<h5>([^<]+)<\/h5>/i);
  if (city) cities.push(city[1].trim());
});

// Extract key messaging/taglines
const taglines = [];
const h2Matches = content.match(/<h2[^>]*>([^<]+)<\/h2>/gi) || [];
h2Matches.forEach(h => {
  const text = cleanText(h.replace(/<[^>]*>/g, ''));
  if (text.length > 10 && text.length < 150 && !text.includes('{')) {
    taglines.push(text);
  }
});

// Extract promotions/offers
const promotions = [];
const promoMatches = content.match(/(\$?\d+%?\s*(?:off|discount))[^<]*/gi) || [];
promoMatches.forEach(p => {
  const promo = cleanText(p);
  if (promo && !promotions.includes(promo)) {
    promotions.push(promo);
  }
});

// Extract membership/pricing info
const membershipMatch = content.match(/\$[\d.]+\s*(?:per|\/)\s*month/gi);
const membershipPrice = membershipMatch ? membershipMatch[0] : '';

// Extract social media links
const socialLinks = {};
const socialPatterns = {
  facebook: /facebook\.com\/([^"'\s?]+)/i,
  instagram: /instagram\.com\/([^"'\s?]+)/i,
  tiktok: /tiktok\.com\/@([^"'\s?]+)/i,
  google: /google\.com[^"'\s]*/i
};
for (const [platform, pattern] of Object.entries(socialPatterns)) {
  const match = content.match(pattern);
  if (match) socialLinks[platform] = match[0];
}

// Extract years in business
const yearMatch = content.match(/since\s*(\d{4})/i);
const yearFounded = yearMatch ? yearMatch[1] : '';

// Extract license number
const licenseMatch = content.match(/TACL[A-Z0-9]+/i);
const licenseNumber = licenseMatch ? licenseMatch[0] : '';

// Build markdown output
let markdown = `# Company Profile: ${companyName || 'Unknown'}\n\n`;

if (metaDescription) {
  markdown += `## About\n${metaDescription}\n\n`;
}

if (yearFounded) {
  markdown += `**In Business Since:** ${yearFounded}\n\n`;
}

if (address) {
  markdown += `## Location\n${address}\n\n`;
}

if (phones.length > 0) {
  markdown += `## Contact\n${phones.join(', ')}\n\n`;
}

if (services.length > 0) {
  markdown += `## Services Offered\n${services.map(s => `- ${s}`).join('\n')}\n\n`;
}

if (values.length > 0) {
  markdown += `## Company Values\n${values.map(v => `- **${v.name}:** ${v.description}`).join('\n')}\n\n`;
}

if (teamMembers.length > 0) {
  markdown += `## Team\n${teamMembers.map(t => `- ${t.name} (${t.role})`).join('\n')}\n\n`;
}

if (cities.length > 0) {
  markdown += `## Service Areas\n${cities.slice(0, 10).join(', ')}${cities.length > 10 ? '...' : ''}\n\n`;
}

if (taglines.length > 0) {
  const uniqueTaglines = [...new Set(taglines)].slice(0, 5);
  markdown += `## Key Messaging\n${uniqueTaglines.map(t => `- "${t}"`).join('\n')}\n\n`;
}

if (promotions.length > 0) {
  markdown += `## Current Promotions\n${[...new Set(promotions)].slice(0, 5).map(p => `- ${p}`).join('\n')}\n\n`;
}

if (membershipPrice) {
  markdown += `## Membership\nOffers membership plan at ${membershipPrice}\n\n`;
}

if (Object.keys(socialLinks).length > 0) {
  markdown += `## Social Presence\n${Object.keys(socialLinks).map(p => `- ${p.charAt(0).toUpperCase() + p.slice(1)}`).join('\n')}\n\n`;
}

if (licenseNumber) {
  markdown += `## Credentials\nLicense: ${licenseNumber}\n`;
}

return {
  json: {
    companyName,
    metaDescription,
    yearFounded,
    address,
    phones,
    services,
    values,
    teamMembers: teamMembers.slice(0, 10),
    serviceAreas: cities,
    taglines: [...new Set(taglines)].slice(0, 5),
    promotions: [...new Set(promotions)].slice(0, 5),
    membershipPrice,
    socialLinks,
    licenseNumber,
    markdownSummary: markdown
  }
};

