const firstMessage = $input.first().json.firstMessage;
const systemPrompt = $input.first().json.systemPrompt;

// Function to make string JSON-safe
function jsonSafeFormat(str) {
  return str
    // Normalize all line breaks to \n
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    // Escape backslashes first (must be first)
    .replace(/\\/g, '\\\\')
    // Escape double quotes
    .replace(/"/g, '\\"')
    // Convert newlines to escaped \n
    .replace(/\n/g, '\\n')
    // Escape tabs
    .replace(/\t/g, '\\t')
    // Remove any control characters that break JSON
    .replace(/[\x00-\x1F\x7F]/g, '')
    // Clean up any multiple spaces
    .replace(/  +/g, ' ')
    // Trim whitespace
    .trim();
}

return {
  json: {
    firstMessage: jsonSafeFormat(firstMessage),
    systemPrompt: jsonSafeFormat(systemPrompt)
  }
};

