// Get the input data
const input = $input.all();

// Initialize result object
let result = {};

// Process each item in the input array
input.forEach(item => {
  try {
    // Get the output string
    let outputString = item.json.output;

    // Clean up the string (remove extra whitespace, newlines)
    outputString = outputString.trim();

    // Parse the JSON string
    const parsedData = JSON.parse(outputString);

    // Dynamically add all keys from parsed data to result
    Object.keys(parsedData).forEach(key => {
      result[key] = parsedData[key];
    });

  } catch (error) {
    // If parsing fails, return error info
    result.error = `Failed to parse: ${error.message}`;
    result.rawOutput = item.json.output;
  }
});

// Return the result as an array with a single object
return [result];

