// Reference the Perplexity node by name (adjust node name if different)
const perplexityData = $('Prospect Research').all();

// Regex pattern to match LinkedIn profile URLs
// Matches: https://linkedin.com/in/username, https://www.linkedin.com/in/username
// Also handles regional subdomains like hk.linkedin.com
const linkedInPattern = /https?:\/\/(?:[a-z]{2}\.)?(?:www\.)?linkedin\.com\/in\/[a-zA-Z0-9_-]+\/?/gi;

// Collect all LinkedIn URLs found (using Set to avoid duplicates)
const linkedInUrls = new Set();

// Function to extract LinkedIn URLs from text
function extractLinkedInUrls(text) {
  if (!text || typeof text !== 'string') return;

  const matches = text.match(linkedInPattern) || [];
  matches.forEach(url => {
    // Clean up trailing slashes for consistency
    const cleanUrl = url.replace(/\/$/, '');
    linkedInUrls.add(cleanUrl);
  });
}

// Recursively search through all properties of an object
function searchObject(obj) {
  if (!obj) return;

  if (typeof obj === 'string') {
    extractLinkedInUrls(obj);
  } else if (Array.isArray(obj)) {
    obj.forEach(item => searchObject(item));
  } else if (typeof obj === 'object') {
    Object.values(obj).forEach(value => searchObject(value));
  }
}

// Search through all items from Perplexity node
perplexityData.forEach(item => {
  searchObject(item.json);
});

// Convert Set to Array
const uniqueUrls = [...linkedInUrls];

// Return output based on whether URLs were found
if (uniqueUrls.length > 0) {
  return [{
    json: {
      status: true,
      LinkedInUrls: uniqueUrls
    }
  }];
} else {
  return [{
    json: {
      status: false
    }
  }];
}

