// Reference the "LinkedIn?" node by name
const linkedInData = $('LinkedIn?').first().json;

// Check if status is true and URLs exist
if (!linkedInData.status || !linkedInData.LinkedInUrls || linkedInData.LinkedInUrls.length === 0) {
  return [{
    json: {
      status: false,
      error: "No LinkedIn URLs found"
    }
  }];
}

// Extract profile IDs from URLs
const profileIds = linkedInData.LinkedInUrls.map(url => {
  // Match the profile ID after /in/ and before any trailing slash or query params
  const match = url.match(/linkedin\.com\/in\/([a-zA-Z0-9_-]+)/);
  return match ? match[1] : null;
}).filter(id => id !== null);

// Return the extracted profile IDs
return [{
  json: {
    status: true,
    profileIds: profileIds,
    // Also return first one separately for easy access in next node
    primaryProfileId: profileIds[0] || null
  }
}];
